package LeetCodeJava.Math;

// https://leetcode.com/problems/find-the-key-of-the-numbers/description/

/**
 * 3270. Find the Key of the Numbers
 * Easy
 *
 * You are given three positive integers num1, num2, and num3.
 *
 * The key of num1, num2, and num3 is defined as a four-digit number such that:
 *
 * Initially, if any number has less than four digits, it is padded with leading zeros.
 * The ith digit (1 <= i <= 4) of the key is generated by taking the smallest digit among the ith digits
 * of num1, num2, and num3.
 *
 * Return the key of the three numbers without leading zeros (if any).
 *
 *
 * Example 1:
 *
 * Input: num1 = 1, num2 = 10, num3 = 1000
 * Output: 0
 * Explanation:
 * On padding, num1 becomes "0001", num2 becomes "0010", and num3 remains "1000".
 * Hence, the key is "0000", i.e. 0.
 *
 * Example 2:
 *
 * Input: num1 = 987, num2 = 879, num3 = 798
 * Output: 777
 *
 * Example 3:
 *
 * Input: num1 = 1, num2 = 2, num3 = 3
 * Output: 1
 *
 *
 * Constraints:
 *
 * 1 <= num1, num2, num3 <= 9999
 *
 */
public class FindTheKeyOfTheNumbers {

    // V0
    // IDEA: DIGIT PEELING — TAKE THE MIN OF THE THREE LAST DIGITS, FOUR TIMES, WEIGHTED BY ITS PLACE VALUE
    //   a missing (padded) digit reads as 0 because the number has already been divided down to 0.
    /**
     * time = O(1)
     * space = O(1)
     */
    public int generateKey(int num1, int num2, int num3) {
        int key = 0;
        int placeValue = 1;
        for (int position = 0; position < 4; position++) {
            int smallestDigit = Math.min(num1 % 10, Math.min(num2 % 10, num3 % 10));
            key += smallestDigit * placeValue;
            placeValue *= 10;
            num1 /= 10;
            num2 /= 10;
            num3 /= 10;
        }
        return key;
    }
}
